def mean_unhappy(p1, p2, num_steps, iters):
    total = 0
    for i in range(iters):
        state = run_simulation(p1, p2, num_steps)
        total += state.olin_empty + state.wellesley_empty
    return total / iters

def annual_growth(series):
    t_0, t_end = get_first_label(series), get_last_label(series)
    p_0, p_end = get_first_value(series), get_last_value(series)
    return (p_end - p_0) / (t_end - t_0)

